import{_ as l,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-07-10:: Ceph DocUBetter meeting","description":"","frontmatter":{"title":"2019-07-10:: Ceph DocUBetter meeting","date":"2019-07-10T00:00:00.000Z","updated":"2019-07-12T00:00:00.000Z","tags":["Ceph","文档改进","分布式存储","开发者体验"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-10_-_-_Ceph_DocUBetter_meeting.md","filePath":"posts/2019/2019-07-10_-_-_Ceph_DocUBetter_meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-07-10_-_-_Ceph_DocUBetter_meeting.md"};function s(n,t,p,a,_,g){return e(),i("div",null,[...t[0]||(t[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Gabriella（Truman大学学生）、Noah（研发人员）、Mike（研发人员）、David Gallery（其他人员）</p><p><strong>会议主题</strong>： 讨论和规划Ceph文档改进，包括网站结构、文档内容、文档构建时间等。</p><p><strong>主要议题及决定</strong>：</p><ol><li><p><strong>文档构建时间优化</strong>：</p><ul><li>Gabriella正在尝试减少文档构建时间，已将Sphinx构建与Python绑定构建分离，但效果尚不理想。</li><li>讨论了使用更现代的文档框架，如实时编辑功能，以提高文档构建效率。</li><li>Noah表示，除非涉及框架变更等根本性问题，否则减少文档构建时间的方法相对简单。</li></ul></li><li><p><strong>文档内容更新</strong>：</p><ul><li>Sarah提到需要更新Docks中的安全组件（safecom）文档，包括为新用户添加新页面或编辑现有页面，使其包含所有必要信息。</li><li>讨论了将Ceph仓库中“Docs”目录中的所有信息整合到Docks中，并对其进行结构化。</li></ul></li><li><p><strong>文档更新要求</strong>：</p><ul><li>强调任何创建PR的人员都应支持文档更新，包括添加新功能或修改配置值。</li><li>如果添加新功能，应至少提供该功能的基本描述，以便用户了解其作用。</li></ul></li><li><p><strong>其他事项</strong>：</p><ul><li>讨论了招聘文档编写人员的进展情况，将在下次会议中更新。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Gabriella继续优化文档构建时间。</li><li>Sarah更新Docks文档。</li><li>所有创建PR的人员注意文档更新的要求。</li><li>下次会议更新招聘文档编写人员的进展情况。</li></ol><p><strong>备注</strong>：</p><ul><li>会议中提到了Ceph的“onboarding”经验，即新用户或新贡献者的入门体验。</li><li>会议强调了提高文档质量和用户体验的重要性。</li></ul><p><strong>改进点</strong>：</p><ul><li>原总结中提到的参会人员Mike和David Gallery的具体身份未在原文中提及，已根据原文内容进行修正。</li><li>原总结中关于文档构建时间优化部分，增加了对更现代文档框架的讨论。</li><li>原总结中关于文档内容更新的部分，明确了Sarah将负责更新Docks文档。</li><li>原总结中关于招聘文档编写人员的进展情况，增加了将在下次会议中更新的信息。</li></ul>",12)])])}const u=l(r,[["render",s]]);export{d as __pageData,u as default};
